#include "reign/bink_movie.hpp"
#include "reign/archive.hpp"
#include <iostream>
#include <fstream>
int main(int argc,char **argv){try{if(argc!=2&&argc!=3)throw std::runtime_error("Usage: bink_probe base.zwp");reign::Archive base(argv[1]);for(int i=0;i<3;++i){auto name="intro-movie-"+std::to_string(i)+".bik";reign::BinkMovie movie(base.read(name));std::size_t samples=0,frames=0;std::uint64_t checksum=0;for(double time=0;time<movie.duration();time+=1./60){if(!movie.advance(time))throw std::runtime_error("Movie ended early");auto pcm=movie.drain_audio();samples+=pcm.size()/2;for(auto p:pcm)checksum=checksum*33+std::uint16_t(p);if(argc==3&&frames==std::size_t(movie.duration()*30)){std::ofstream out(std::string(argv[2])+"-"+std::to_string(i)+".ppm",std::ios::binary);out<<"P6\n"<<movie.width()<<' '<<movie.height()<<"\n255\n";auto &pixels=movie.rgba();for(std::size_t p=0;p<pixels.size();p+=4)out.write(reinterpret_cast<const char*>(pixels.data()+p),3);if(!out)throw std::runtime_error("Frame write failed");}++frames;}if(movie.advance(movie.duration()))throw std::runtime_error("Movie failed to end");std::cout<<name<<" "<<movie.width()<<"x"<<movie.height()<<" duration="<<movie.duration()<<" sample-rate="<<movie.sample_rate()<<" stereo-samples="<<samples<<" display-frames="<<frames<<" audio-checksum="<<checksum<<'\n';}for(int i=0;i<3;++i){auto data=base.read("intro-movie-"+std::to_string(i)+".bik");reign::BinkMovie continuous(data),restored(data);double target=continuous.duration()*.5;
 for(double t=0;t<target;t+=1./60){continuous.advance(t);continuous.drain_audio();}continuous.advance(target);continuous.drain_audio();restored.restore_position(target);
 if(continuous.frame_index()!=restored.frame_index()||continuous.rgba()!=restored.rgba()||!restored.drain_audio().empty())throw std::runtime_error("Restored movie frame differs");
 continuous.advance(target+.1);restored.advance(target+.1);if(continuous.rgba()!=restored.rgba()||continuous.drain_audio()!=restored.drain_audio())throw std::runtime_error("Restored movie continuation differs");
 bool rejected=false;try{restored.restore_position(0);}catch(const std::invalid_argument&){rejected=true;}if(!rejected)throw std::runtime_error("Restore accepted a used decoder");
 }std::cout<<"Original Bink video/audio decode and checkpoint continuation: PASS\n";}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}}
